#include <iostream>
#include <map>
#include <set>
#include <sstream>
int main(){int n,m;if(!(std::cin>>n>>m)||n<0||n>32||m<0||m>32){std::cout<<"invalid\n";return 0;}
 std::map<int,int>a,b;std::set<int>keys;
 for(int part=0;part<2;++part)for(int i=0;i<(part==0?n:m);++i){int id,value;if(!(std::cin>>id>>value)||id<1||id>9999||value< -10000||value>10000){std::cout<<"invalid\n";return 0;}auto&current=part==0?a:b;if(!current.emplace(id,value).second){std::cout<<"invalid\n";return 0;}keys.insert(id);}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 std::ostringstream report;int changes=0;
 for(int id:keys){auto old=a.find(id),now=b.find(id);if(old==a.end()){report<<"new "<<id<<' '<<now->second<<'\n';++changes;}else if(now==b.end()){report<<"removed "<<id<<' '<<old->second<<'\n';++changes;}else if(old->second!=now->second){report<<"changed "<<id<<' '<<old->second<<' '<<now->second<<'\n';++changes;}}
 std::cout<<(changes?report.str():"no-change\n");
}
